bool write(BitWriter& bits, const CmdEvent& value) {
    if (!writeUnsigned(bits, value.cmdFlags, UINT64_C(0), UINT64_C(67108863), 26))
        return false;
    if (!writeBool(bits, value.abil.has_value()))
        return false;
    if (value.abil) {
        if (!write(bits, (*value.abil)))
            return false;
    }
    if (!write(bits, value.data))
        return false;
    if (!writeUnsigned(bits, value.sequence, UINT64_C(1), UINT64_C(4294967295), 32))
        return false;
    if (!writeBool(bits, value.otherUnit.has_value()))
        return false;
    if (value.otherUnit) {
        if (!writeUnsigned(bits, (*value.otherUnit), UINT64_C(0), UINT64_C(4294967295), 32))
            return false;
    }
    if (!writeBool(bits, value.unitGroup.has_value()))
        return false;
    if (value.unitGroup) {
        if (!writeUnsigned(bits, (*value.unitGroup), UINT64_C(0), UINT64_C(4294967295), 32))
            return false;
    }
    return true;
}

