bool write(BitWriter& bits, const GameUserJoinEvent& value) {
    if (!write(bits, value.observe))
        return false;
    if (!writeString(bits, value.name, 6, UINT64_C(32)))
        return false;
    if (!writeBool(bits, value.toonHandle.has_value()))
        return false;
    if (value.toonHandle) {
        if (!writeString(bits, (*value.toonHandle), 5, UINT64_C(19)))
            return false;
    }
    if (!writeBool(bits, value.clanTag.has_value()))
        return false;
    if (value.clanTag) {
        if (!writeString(bits, (*value.clanTag), 6, UINT64_C(32)))
            return false;
    }
    if (!writeBool(bits, value.clanLogo.has_value()))
        return false;
    if (value.clanLogo) {
        if (!writeFixedBlob(bits, (*value.clanLogo), 40))
            return false;
    }
    if (!writeBool(bits, value.hijack))
        return false;
    if (!writeBool(bits, value.hijackCloneGameUserId.has_value()))
        return false;
    if (value.hijackCloneGameUserId) {
        if (!writeUnsigned(bits, (*value.hijackCloneGameUserId), UINT64_C(0), UINT64_C(15), 4))
            return false;
    }
    return true;
}

bool read(BitReader& bits, GameUserJoinEvent& value) {
    if (!read(bits, value.observe))
        return false;
    if (!readString(bits, value.name, 6, UINT64_C(32)))
        return false;
    {
        bool present = false;
        if (!readBool(bits, present))
            return false;
        if (present) {
            value.toonHandle.emplace();
            if (!readString(bits, (*value.toonHandle), 5, UINT64_C(19)))
                return false;
        } else {
            value.toonHandle.reset();
        }
    }
    {
        bool present = false;
        if (!readBool(bits, present))
            return false;
        if (present) {
            value.clanTag.emplace();
            if (!readString(bits, (*value.clanTag), 6, UINT64_C(32)))
                return false;
        } else {
            value.clanTag.reset();
        }
    }
    {
        bool present = false;
        if (!readBool(bits, present))
            return false;
        if (present) {
            value.clanLogo.emplace();
            (*value.clanLogo).assign(40, std::byte{0});
            if (!readFixedBlob(bits, (*value.clanLogo)))
                return false;
        } else {
            value.clanLogo.reset();
        }
    }
    if (!readBool(bits, value.hijack))
        return false;
    {
        bool present = false;
        if (!readBool(bits, present))
            return false;
        if (present) {
            value.hijackCloneGameUserId.emplace();
            {
                std::uint64_t raw = 0;
                if (!readUnsigned(bits, raw, UINT64_C(0), UINT64_C(15), 4))
                    return false;
                (*value.hijackCloneGameUserId) = static_cast<std::uint8_t>(raw);
            }
        } else {
            value.hijackCloneGameUserId.reset();
        }
    }
    return true;
}

