bool write(BitWriter& bits, const ConvertToReplaySessionEvent& value) {
    if (!writeBool(bits, value.replayJumpGameLoop.has_value()))
        return false;
    if (value.replayJumpGameLoop) {
        if (!writeSigned(bits, (*value.replayJumpGameLoop), INT64_C(-2147483648),
                         UINT64_C(2147483647), 32))
            return false;
    }
    return true;
}

bool read(BitReader& bits, ConvertToReplaySessionEvent& value) {
    {
        bool present = false;
        if (!readBool(bits, present))
            return false;
        if (present) {
            value.replayJumpGameLoop.emplace();
            {
                std::int64_t raw = 0;
                if (!readSigned(bits, raw, INT64_C(-2147483648), UINT64_C(2147483647), 32))
                    return false;
                (*value.replayJumpGameLoop) = static_cast<std::int32_t>(raw);
            }
        } else {
            value.replayJumpGameLoop.reset();
        }
    }
    return true;
}

